+static void fill_create_jetty_attr(struct ubcore_jetty_cfg *cfg,
+				   const struct uburma_cmd_create_jetty *arg)
+{
+	cfg->id = arg->in.id;
+	cfg->jfs_depth = arg->in.jfs_depth;
